4	public class Climate {
5	
6		private static final int SEASON_LENGTH = 16;
7	
8		private static final int MIN_HUMIDITY_CHANGE = 10;
9	
10		private static final int MAX_HUMIDITY_CHANGE = 20;
11	
12		private static final Random rand = Randomizer.getRandom();
13	
14		private Weather currentWeather;
15	
16		private Season currentSeason;
17	
18		private int humidity;
19	
20	
21		public Climate(Weather currentWeather) {
22			this.currentWeather = currentWeather;
23			currentSeason = Season.SPRING;
24		}
25	
26	
27		public void updateClimate(int step) {
28			updateSeason(step);
29	
30	
31			int humidityIncrease = rand.nextInt(MAX_HUMIDITY_CHANGE - MIN_HUMIDITY_CHANGE + 1) + MIN_HUMIDITY_CHANGE;
32	
33			if (humidity < 80 && (currentWeather == Weather.SUN || currentWeather == Weather.CLOUD)) {
34				humidity += humidityIncrease;
35			} else if (humidity < 100 && (currentWeather == Weather.SUN || currentWeather == Weather.CLOUD)) {
36				humidity += humidityIncrease;
37				currentWeather = Weather.CLOUD;
38			} else if (humidity > 100 && (currentWeather == Weather.SUN || currentWeather == Weather.CLOUD) && currentSeason != Season.WINTER) {
39				currentWeather = Weather.RAIN;
40			} else if (humidity > 80 && currentWeather == Weather.RAIN) {
41				humidity -= humidityIncrease;
42			} else {
43				humidity = 0;
44				currentWeather = Weather.SUN;
45			}
46		}
47	
48	
49		private void updateSeason(int step) {
50			switch ((step / SEASON_LENGTH) % 4) {
51				case 0:
52					currentSeason = Season.SPRING;
53					break;
54				case 1:
55					currentSeason = Season.SUMMER;
56					break;
57				case 2:
58					currentSeason = Season.AUTUMN;
