90			private int[] lastVal;
91			private int yMax;
92	
93	
94			public GraphPanel(int width, int height, int startMax) {
95				graphImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
96				clearImage();
97				lastVal = new int[classes.size()];
98				Arrays.fill(lastVal, height);
99				yMax = startMax;
100			}
