103			public void newRun() {
104				int height = graphImage.getHeight();
105				int width = graphImage.getWidth();
106	
107				Graphics g = graphImage.getGraphics();
108				g.copyArea(4, 0, width - 4, height, -4, 0);
109				g.setColor(Color.BLACK);
110				g.drawLine(width - 4, 0, width - 4, height);
111				g.drawLine(width - 2, 0, width - 2, height);
112				lastVal = new int[classes.size()];
113				Arrays.fill(lastVal, height);
114				repaint();
115			}
