160	
161				BufferedImage tmpImage = new BufferedImage(width, (int) (height * SCALE_FACTOR),
162						BufferedImage.TYPE_INT_RGB);
163				Graphics2D gtmp = (Graphics2D) tmpImage.getGraphics();
164	
165				gtmp.scale(1.0, SCALE_FACTOR);
166				gtmp.drawImage(graphImage, 0, 0, null);
167	
168				int oldTop = (int) (height * (1.0 - SCALE_FACTOR));
169	
170				g.setColor(Color.WHITE);
171				g.fillRect(0, 0, width, oldTop);
172				g.drawImage(tmpImage, 0, oldTop, null);
173	
174				yMax = (int) (yMax / SCALE_FACTOR);
175	
176				for (int i = 0; i < lastVal.length; i++) {
177					lastVal[i] = oldTop + (int) (lastVal[i] * SCALE_FACTOR);
178				}
179	
180				repaint();
181			}
